<template>
  <main class="calculator-page" :aria-busy="loading ? 'true' : 'false'">
    <header class="page-header"><div><p>{{ copy.eyebrow }}</p><h1>{{ copy.title }}</h1><span>{{ copy.subtitle }}</span></div></header>
    <div class="calculator-layout">
      <section class="quote-panel">
        <div class="route-strip"><span><small>{{ copy.from }}</small><strong>{{ copy.china }}</strong></span><i class="el-icon-right"></i><label><small>{{ copy.to }}</small><select v-model="form.countryCode"><option v-for="country in countries" :key="countryCode(country)" :value="countryCode(country)">{{ countryName(country) }}</option></select></label></div>
        <form @submit.prevent="calculate">
          <div class="form-section"><div><span>1</span><strong>{{ copy.destination }}</strong></div><div class="two"><label><span>{{ copy.postal }}</span><input v-model.trim="form.zipcode" autocomplete="postal-code" :placeholder="copy.postalPlaceholder" /></label><label><span>{{ copy.addressType }}</span><select v-model.number="form.addressType"><option :value="1">{{ copy.business }}</option><option :value="2">{{ copy.residential }}</option><option :value="3">Amazon FBA</option></select></label></div></div>
          <div class="form-section"><div><span>2</span><strong>{{ copy.package }}</strong></div><div class="package-grid"><label><span>{{ copy.length }}</span><input v-model.number="form.length" type="number" min="0.1" step="0.1" required /></label><label><span>{{ copy.width }}</span><input v-model.number="form.width" type="number" min="0.1" step="0.1" required /></label><label><span>{{ copy.height }}</span><input v-model.number="form.height" type="number" min="0.1" step="0.1" required /></label><label><span>{{ copy.weight }}</span><input v-model.number="form.weight" type="number" min="0.1" step="0.1" required /></label><label><span>{{ copy.quantity }}</span><input v-model.number="form.quantity" type="number" min="1" step="1" required /></label></div><p>{{ copy.units }}</p></div>
          <div class="trust"><i class="el-icon-lock"></i><span><strong>{{ copy.realQuote }}</strong><small>{{ copy.realQuoteCopy }}</small></span></div>
          <p v-if="error" class="form-error">{{ error }}</p>
          <button class="primary" type="submit" :disabled="loading || !countries.length">{{ loading ? copy.calculating : copy.calculate }}</button>
        </form>
      </section>

      <aside class="summary-panel">
        <template v-if="!searched"><i class="el-icon-truck"></i><h2>{{ copy.ready }}</h2><p>{{ copy.readyCopy }}</p></template>
        <template v-else-if="!quotes.length && !loading"><i class="el-icon-search"></i><h2>{{ copy.noRates }}</h2><p>{{ copy.noRatesCopy }}</p></template>
        <template v-else><div class="result-heading"><div><p>{{ copy.rates }}</p><h2>{{ quotes.length }} {{ copy.options }}</h2></div><span>{{ copy.sorted }}</span></div><article v-for="(quote,index) in quotes" :key="quote.vendor_code || quote.id || index" class="quote-card"><div><img v-if="quote.product_img" :src="quote.product_img" alt="" /><span><strong>{{ quote.product_name_e || quote.product_name || copy.shipping }}</strong><small>{{ quote.aging_start || '-' }}-{{ quote.aging_end || '-' }} {{ copy.days }}</small></span></div><strong>{{ money(quote.freight ?? quote.total_price ?? quote.price) }}</strong><footer><span>{{ Number(quote.tax) === 1 ? copy.taxIncluded : copy.taxCalculated }}</span><router-link :to="{ path: '/admin/workspace/checkout', query: { shipping: quote.vendor_code || quote.id } }">{{ copy.useRate }}</router-link></footer></article></template>
      </aside>
    </div>
  </main>
</template>

<script>
import { getShippingCost, shipFromTo } from '@/api/shippingCost'
export default {
  name: 'WorkspaceShippingCalculator',
  data() { return { countries: [], loading: false, searched: false, error: '', quotes: [], form: { countryCode: 'US', zipcode: '', addressType: 1, length: 30, width: 20, height: 15, weight: 2, quantity: 1 } } },
  computed: {
    chinese() { return String(this.$workspaceLocale?.locale || '').toLowerCase().startsWith('zh') },
    copy() { return this.chinese ? { eyebrow: '采购工具', title: '国际运费计算', subtitle: '输入真实包裹信息，查看 CoDropshipping 当前可用的物流方案。最终费用以下单审核为准。', from: '发货地', china: '中国仓', to: '目的地', destination: '填写目的地', postal: '邮编（建议填写）', postalPlaceholder: '例如 10001', addressType: '地址类型', business: '商业地址', residential: '住宅地址', package: '填写一个包裹', length: '长', width: '宽', height: '高', weight: '重量', quantity: '箱数', units: '尺寸单位为厘米（CM），重量单位为千克（KG）。', realQuote: '调用真实运费接口', realQuoteCopy: '页面不会展示虚构或演示价格。', calculate: '获取运费方案', calculating: '正在计算…', ready: '准备计算运费', readyCopy: '选择目的地并填写包裹尺寸，结果将在这里显示。', noRates: '暂时没有匹配方案', noRatesCopy: '请检查目的地、邮编和包裹尺寸，或联系客户经理询价。', rates: '可用方案', options: '个选项', sorted: '按价格排序', shipping: '国际物流', days: '天', taxIncluded: '含税方案', taxCalculated: '税费以审核为准', useRate: '用于采购订单', serviceError: '运费服务暂时不可用，请稍后重试。', selectError: '目的地列表暂时不可用。' } : { eyebrow: 'Sourcing tool', title: 'International shipping calculator', subtitle: 'Enter real package details to see currently available CoDropshipping shipping services. Final charges are confirmed during order review.', from: 'Ship from', china: 'China warehouse', to: 'Destination', destination: 'Choose the destination', postal: 'Postal code (recommended)', postalPlaceholder: 'For example 10001', addressType: 'Address type', business: 'Business address', residential: 'Residential address', package: 'Describe one package', length: 'Length', width: 'Width', height: 'Height', weight: 'Weight', quantity: 'Cartons', units: 'Dimensions use centimeters (CM); weight uses kilograms (KG).', realQuote: 'Uses the live shipping rate service', realQuoteCopy: 'No sample or invented prices are shown.', calculate: 'Get shipping rates', calculating: 'Calculating…', ready: 'Ready to calculate', readyCopy: 'Choose a destination and enter package dimensions. Available services will appear here.', noRates: 'No matching service found', noRatesCopy: 'Check the destination, postal code and package size, or ask your account manager for a quote.', rates: 'Available rates', options: 'options', sorted: 'Lowest price first', shipping: 'International shipping', days: 'days', taxIncluded: 'Tax-inclusive service', taxCalculated: 'Tax confirmed on review', useRate: 'Use for sourcing order', serviceError: 'Shipping rates are temporarily unavailable. Try again.', selectError: 'Destinations are temporarily unavailable.' } },
  },
  async mounted() { try { const response = await shipFromTo(); this.countries = response?.data?.endCountry || []; if (!this.countries.some((item) => this.countryCode(item) === this.form.countryCode) && this.countries[0]) this.form.countryCode = this.countryCode(this.countries[0]) } catch (error) { this.error = error?.message || this.copy.selectError } },
  methods: {
    countryCode(country) { return country.code_two || country.iso2 || country.code || '' },
    countryName(country) { return country.en_nickname || country.name || country.zh_cn_nickname || this.countryCode(country) },
    async calculate() { const destination = this.countries.find((item) => this.countryCode(item) === this.form.countryCode); if (!destination) return; this.loading = true; this.searched = true; this.error = ''; this.quotes = []; const params = { shipping_from: '100000', shipping_from_en: 'China', take: 1, shipping_to: destination.zh_cn_nickname || destination.name || this.form.countryCode, shipping_to_en: destination.en_nickname || destination.name || this.form.countryCode, shipping_to_zipcode: this.form.zipcode, shipping_to_type: this.form.addressType, not_fba_address: this.form.addressType === 3 ? 0 : 1, insurance: 0, load_type: 1, volume: `${this.form.length},${this.form.width},${this.form.height}`, volume_unit: 1, weight: String(this.form.weight), weight_unit: 1, total: String(this.form.quantity), product_one: 0, product_two: 0 }; try { const response = await getShippingCost(params); if (Number(response?.code ?? 0) !== 0) throw new Error(response?.msg || this.copy.serviceError); const rows = Array.isArray(response?.data) ? response.data : []; this.quotes = rows.slice().sort((a,b) => Number(a.freight || a.total_price || Infinity) - Number(b.freight || b.total_price || Infinity)) } catch (error) { this.error = error?.message || this.copy.serviceError } finally { this.loading = false } },
    money(value) { const amount = Number(value); return Number.isFinite(amount) ? new Intl.NumberFormat(this.$workspaceLocale?.locale || 'en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 }).format(amount) : '-' },
  },
}
</script>

