margin:9px 0 0;color:#788079;font-size:12px}.trust{display:flex;align-items:center;gap:11px;padding:14px;border-radius:9px;background:#eef6f0;color:#296849}.trust>i{font-size:19px}.trust strong,.trust small{display:block}.trust small{margin-top:3px;font-size:12px}.primary{min-height:47px;border:0;border-radius:8px;background:#e45620;color:#fff;font:inherit;font-weight:850;cursor:pointer}.primary:disabled{opacity:.55;cursor:not-allowed}.form-error{margin:0;padding:12px;border-radius:8px;background:#fff0ec;color:#963d2b}.summary-panel{min-height:400px;padding:22px}.summary-panel>i{width:50px;height:50px;display:grid;place-items:center;margin:75px auto 0;border-radius:13px;background:#fff0e8;color:#d14f1c;font-size:23px}.summary-panel>h2,.summary-panel>p{text-align:center}.summary-panel>h2{margin:16px 0 6px}.summary-panel>p{max-width:380px;margin:0 auto;color:#6c756d;line-height:1.5}.result-heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:12px}.result-heading h2{margin:0}.result-heading>span{color:#737c74;font-size:12px}.quote-card{padding:17px 0;border-top:1px solid #e1e6e1}.quote-card>div{display:grid;grid-template-columns:46px minmax(0,1fr);align-items:center;gap:11px}.quote-card img{width:46px;height:46px;border-radius:8px;object-fit:contain;background:#f1f3f0}.quote-card>div>span strong,.quote-card>div>span small{display:block}.quote-card>div>span small{margin-top:4px;color:#69736b;font-size:12px}.quote-card>strong{display:block;margin:13px 0;color:#d34f1d;font-size:24px}.quote-card footer{display:flex;justify-content:space-between;gap:12px;color:#747d75;font-size:12px}.quote-card footer a{color:#aa431d;font-weight:800}@media(max-width:1100px){.calculator-layout{grid-template-columns:1fr}.summary-panel{min-height:300px}.summary-panel>i{margin-top:40px}}@media(max-width:720px){.calculator-page{padding:25px 16px 50px}.two{grid-template-columns:1fr}.package-grid{grid-template-columns:repeat(2,1fr)}.package-grid label:last-child{grid-column:1/-1}.route-strip{grid-template-columns:1fr 28px 1fr;padding:18px}}
</style>
